def signed(poly):
 m=np.zeros((720,1280),np.uint8);cv2.fillPoly(m,[np.asarray(poly,np.int32)],255)
 return cv2.distanceTransform(m,cv2.DIST_L2,3)-cv2.distanceTransform(255-m,cv2.DIST_L2,3)

def prior(frame):
 if 168<=frame<=215:
  p=np.asarray(SMALL,float);p[:,0]=650+(p[:,0]-650)*(1-(frame-168)*.002);p[:,1]+=(frame-168)*.16
  # At the end, the second rider physically occludes the small rider's right arm.
  m=(signed(p)>0).astype(np.uint8)*255
  if frame>=208:
   x=int(858-(frame-208)*15);cv2.fillPoly(m,[np.array([(x,510),(1280,510),(1280,720),(715,720),(730,580)],np.int32)],0)
  return m
 keys=[k for k in POLYGONS if (k<=98 if frame<=98 else 154<=k<=167 if frame<=167 else 221<=k<=225 if frame<=225 else k>=394)]
 lo=max(k for k in keys if k<=frame);hi=min(k for k in keys if k>=frame)
 if lo==hi:return np.uint8(signed(POLYGONS[lo])>0)*255
 u=(frame-lo)/(hi-lo)
 return np.uint8((1-u)*signed(POLYGONS[lo])+u*signed(POLYGONS[hi])>0)*255

def refine(im,mask,frame):
 # A narrow uncertainty band prevents other dark background riders being selected.
 radius=6
 er=cv2.erode(mask,np.ones((radius*2+1,radius*2+1),np.uint8))
 di=cv2.dilate(mask,np.ones((radius*2+1,radius*2+1),np.uint8))
 labels=np.zeros(mask.shape,np.uint8);labels[di>0]=cv2.GC_PR_BGD;labels[mask>0]=cv2.GC_PR_FGD;labels[er>0]=cv2.GC_FGD
 bg=np.zeros((1,65));fg=np.zeros((1,65));cv2.grabCut(im,labels,None,bg,fg,2,cv2.GC_INIT_WITH_MASK)
 out=np.uint8((labels==1)|(labels==3))*255
 return cv2.GaussianBlur(out,(3,3),.55)

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--video',type=Path,default=ROOT/'media/reference.mp4');ap.add_argument('--out',type=Path,default=ROOT/'assets/subject_masks');ap.add_argument('--frames',nargs='*',type=int);args=ap.parse_args()
 args.out.mkdir(exist_ok=True,parents=True);cv2.setNumThreads(2);cv2.setRNGSeed(329796);cap=cv2.VideoCapture(str(args.video))
 frames=args.frames or list(range(99))+list(range(154,216))+list(range(221,226))+list(range(394,427))
 for f in frames:
  cap.set(cv2.CAP_PROP_POS_FRAMES,f);ok,im=cap.read()
  if not ok:raise RuntimeError(f)
  im=cv2.rotate(im,cv2.ROTATE_90_COUNTERCLOCKWISE);mask=refine(im,prior(f),f);cv2.imwrite(str(args.out/f'{f:04}.png'),mask)
  if f%15==0:print(f,flush=True)
 report={'method':'manual silhouette anchors, signed-distance interpolation, boundedGrabCut refinement2iterations; feather0.55px','orientation':'90CCW,1280x720','frames':sorted(int(x.stem) for x in args.out.glob('[0-9][0-9][0-9][0-9].png')),'source_rgb':'unchanged; only mask outputs','limitations':['No cached segmentation model used.','Dark overlapping background riders may retain6px local contamination; no large background rider selection permitted.','Small rider partially occluded by foreground rider at208..215; visible-only manual clipping.','Frame98 is separate ciano transition; source cyan color intentionally unchanged.','Thin antennae and motorcycle peripheral parts are lower confidence.'],'anchors':POLYGONS,'small_anchor':SMALL}
 (args.out/'mask-provenance.json').write_text(json.dumps(report,indent=2))
 cap.release()
 qa(args.video,args.out)

def qa(video,out):
 frames=[0,15,30,45,60,75,90,96,98,154,160,167,168,180,195,214,221,225,394,426]
 cap=cv2.VideoCapture(str(video));contact=np.zeros((760,1600,3),np.uint8)
 for i,f in enumerate(frames):
  mp=out/f'{f:04}.png'
  if not mp.exists():continue
  cap.set(cv2.CAP_PROP_POS_FRAMES,f);ok,im=cap.read()
  if not ok:continue
  im=cv2.rotate(im,cv2.ROTATE_90_COUNTERCLOCKWISE);alpha=cv2.imread(str(mp),0).astype(float)[:,:,None]/255
  bg=np.full_like(im,(180,80,120));im=np.uint8(im*alpha+bg*(1-alpha));im=cv2.resize(im,(320,180));cv2.putText(im,str(f),(5,18),cv2.FONT_HERSHEY_SIMPLEX,.5,(0,255,255),1,cv2.LINE_AA)
  contact[(i//5)*190:(i//5)*190+180,(i%5)*320:(i%5)*320+320]=im
 cv2.imwrite(str(out/'qa-contact.jpg'),contact);cap.release()
